// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Page the append-only human action audit ledger (admin only)
	// (GET /admin/audit)
	ListAdminAudit(c *gin.Context, params ListAdminAuditParams)
	// Add one documentation link to the shared aggregation list (admin only)
	// (POST /admin/documentation/links)
	CreateAdminDocumentationLink(c *gin.Context)
	// Remove one documentation link from the shared list (admin only)
	// (DELETE /admin/documentation/links/{key})
	DeleteAdminDocumentationLink(c *gin.Context, key string)
	// Replace one documentation link's title, URL, and embed flag (admin only)
	// (PATCH /admin/documentation/links/{key})
	UpdateAdminDocumentationLink(c *gin.Context, key string)
	// List every RuntimeEnvironment across users with lifecycle state (admin only)
	// (GET /admin/environments)
	ListAdminEnvironments(c *gin.Context)
	// Request an administrative environment release via the existing drain path (admin only)
	// (POST /admin/environments/{name}/release)
	ReleaseAdminEnvironment(c *gin.Context, name string)
	// Observe the runnable action queue with backlog summary and flags (admin only)
	// (GET /admin/runnable-actions)
	ListAdminRunnableActions(c *gin.Context, params ListAdminRunnableActionsParams)
	// Observe the durable reap queue behind environment teardown (admin only)
	// (GET /admin/runnable-reaps)
	ListAdminRunnableReaps(c *gin.Context)
	// Server build, catalog integrity, and background service registry (admin only)
	// (GET /admin/system)
	GetAdminSystem(c *gin.Context)
	// List user accounts without credentials (admin only)
	// (GET /admin/users)
	ListAdminUsers(c *gin.Context)
	// Replace a user's TOTP secret after the caller confirms their own password (admin only)
	// (POST /admin/users/{id}/totp-reset)
	ResetAdminUserTOTP(c *gin.Context, id string)
	// Login with password + TOTP
	// (POST /auth/login)
	Login(c *gin.Context)
	// Register a new user; the first registered user becomes admin
	// (POST /auth/register)
	Register(c *gin.Context)
	// Remove an author-owned Scenario from the active Catalog
	// (POST /authoring/scenarios/{id}/deprecate)
	DeprecateAuthoringScenario(c *gin.Context, id string)
	// Start a new authoring session for an author-owned Scenario revision
	// (POST /authoring/scenarios/{id}/revisions)
	CreateAuthoringScenarioRevision(c *gin.Context, id string)
	// Create a human-reviewed scenario authoring session
	// (POST /authoring/sessions)
	CreateAuthoringSession(c *gin.Context)
	// Resume the latest unfinished authoring session for the current user
	// (GET /authoring/sessions/current)
	GetCurrentAuthoringSession(c *gin.Context)
	// Read the current authoring revision, conversation, assets, and diff
	// (GET /authoring/sessions/{id})
	GetAuthoringSession(c *gin.Context, id AuthoringSessionID)
	// Send one natural-language instruction to the authoring agent
	// (POST /authoring/sessions/{id}/messages)
	SendAuthoringMessage(c *gin.Context, id AuthoringSessionID)
	// List every documentation link in creation order (public read)
	// (GET /documentation/links)
	ListDocumentationLinks(c *gin.Context)
	// Create or revise one user-owned generation plan
	// (POST /generator/plans)
	SetGenerationPlan(c *gin.Context)
	// List the authenticated user's unfinished generation workflows
	// (GET /generator/workflows)
	ListActiveGenerations(c *gin.Context)
	// Confirm one persisted plan revision and create its workflow
	// (POST /generator/workflows)
	ConfirmGeneration(c *gin.Context)
	// Read one user-owned workflow and its safe candidate review projection
	// (GET /generator/workflows/{workflow_id})
	GetGeneration(c *gin.Context, workflowId GeneratorWorkflowID)
	// Cancel one unfinished generation workflow
	// (POST /generator/workflows/{workflow_id}/cancel)
	CancelGeneration(c *gin.Context, workflowId GeneratorWorkflowID)
	// Submit the archive from one bound workspace turn as an immutable candidate
	// (POST /generator/workflows/{workflow_id}/candidate)
	SubmitGeneratorCandidate(c *gin.Context, workflowId GeneratorWorkflowID)
	// Return a reviewed candidate to generating with user feedback
	// (POST /generator/workflows/{workflow_id}/content/changes)
	RequestGeneratorContentChanges(c *gin.Context, workflowId GeneratorWorkflowID)
	// Confirm a verified candidate and begin publication
	// (POST /generator/workflows/{workflow_id}/content/confirm)
	ConfirmGeneratorContent(c *gin.Context, workflowId GeneratorWorkflowID)
	// Download one immutable author review bundle
	// (GET /generator/workflows/{workflow_id}/review-bundle)
	GetGeneratorReviewBundle(c *gin.Context, workflowId GeneratorWorkflowID, params GetGeneratorReviewBundleParams)
	// Run one command inside a bound generator workspace turn
	// (POST /generator/workflows/{workflow_id}/workspace/commands)
	RunGeneratorWorkspaceCommand(c *gin.Context, workflowId GeneratorWorkflowID)
	// Read a relative file from one bound generator workspace turn
	// (GET /generator/workflows/{workflow_id}/workspace/file)
	ReadGeneratorWorkspaceFile(c *gin.Context, workflowId GeneratorWorkflowID, params ReadGeneratorWorkspaceFileParams)
	// List files in one bound generator workspace turn
	// (GET /generator/workflows/{workflow_id}/workspace/files)
	ListGeneratorWorkspaceFiles(c *gin.Context, workflowId GeneratorWorkflowID, params ListGeneratorWorkspaceFilesParams)
	// Write one relative file in a bound generator workspace turn
	// (PUT /generator/workflows/{workflow_id}/workspace/files)
	WriteGeneratorWorkspaceFile(c *gin.Context, workflowId GeneratorWorkflowID)
	// Bind one explicit generator turn to a workflow workspace
	// (POST /generator/workflows/{workflow_id}/workspace/turn)
	StartGeneratorWorkspaceTurn(c *gin.Context, workflowId GeneratorWorkflowID)
	// Release one explicit generator workspace turn
	// (POST /generator/workflows/{workflow_id}/workspace/turn/end)
	EndGeneratorWorkspaceTurn(c *gin.Context, workflowId GeneratorWorkflowID)
	// Get the authenticated user's learning space
	// (GET /me/space)
	GetMySpace(c *gin.Context)
	// Page durable learning history for the authenticated user
	// (GET /me/space/learning)
	GetMySpaceLearning(c *gin.Context, params GetMySpaceLearningParams)
	// List operations scenarios
	// (GET /operations/scenarios)
	ListScenarios(c *gin.Context)
	// Read or create the assistant conversation for the active scenario environment
	// (GET /operations/scenarios/{id}/assistant)
	GetScenarioAssistant(c *gin.Context, id string)
	// Send a message to the active scenario assistant and receive SSE events
	// (POST /operations/scenarios/{id}/assistant/messages)
	SendScenarioAssistantMessage(c *gin.Context, id string)
	// Get scenario details and any available learning aids
	// (GET /operations/scenarios/{id}/content)
	GetScenarioContent(c *gin.Context, id string)
	// Read the controller-owned current scenario checkpoint snapshot
	// (GET /operations/scenarios/{id}/progress)
	GetScenarioProgress(c *gin.Context, id string)
	// Reset scenario to initial state
	// (POST /operations/scenarios/{id}/reset)
	ResetScenario(c *gin.Context, id string)
	// Start or resume a scenario environment
	// (POST /operations/scenarios/{id}/start)
	StartScenario(c *gin.Context, id string)
	// Stop the current scenario environment
	// (POST /operations/scenarios/{id}/stop)
	StopScenario(c *gin.Context, id string)
	// Create a one-time ticket for a terminal WebSocket
	// (POST /operations/scenarios/{id}/terminal-ticket)
	CreateTerminalTicket(c *gin.Context, id string)
	// Close one terminal tab in the current scenario environment
	// (DELETE /operations/scenarios/{id}/terminals/{window})
	CloseTerminalWindow(c *gin.Context, id string, window string, params CloseTerminalWindowParams)
	// Close the playground and release its resources (JWT)
	// (DELETE /playground)
	ClosePlayground(c *gin.Context)
	// Report the user's playground session (JWT)
	// (GET /playground)
	GetPlayground(c *gin.Context)
	// Create or adopt the user's playground (JWT)
	// (POST /playground)
	CreatePlayground(c *gin.Context)
	// Wipe the playground to a fresh state (JWT)
	// (POST /playground/reset)
	ResetPlayground(c *gin.Context)
	// Create a one-time ticket for the playground terminal WebSocket (JWT)
	// (POST /playground/terminal-ticket)
	CreatePlaygroundTerminalTicket(c *gin.Context)
}

